    const float step = dt * 30.f;
    if (!isfinite(base) || !isfinite(multiplier) || !(multiplier > 0.f) ||
        !isfinite(gain) || !(gain > 0.f && gain < 1.f) ||
        !isfinite(dt) || dt < 0.f || dt > .1f || step == 1.f) return bits;
    base = -expm1f(log1pf(-gain) * step) / multiplier;
    memcpy(&bits, &base, 4);
    return bits;
